 function dialog(title,body){document.getElementById('up-dialog')?.remove();const d=document.createElement('dialog');d.id='up-dialog';d.className='up-dialog';d.setAttribute('aria-labelledby','up-dialog-title');d.innerHTML=`<div class="up-dialog-header"><h2 id="up-dialog-title">${title}</h2><button type="button" class="up-dialog-close" data-up-close aria-label="${t('Cerrar','Close')}">×</button></div>${body}<p class="up-error" data-up-dialog-status role="alert"></p>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
