 let mediaGeneration=0;
 const previewCache=new Map();
 function releasePreviews(){const viewer=document.getElementById('up-dialog');if(viewer?.classList?.contains('up-preview-dialog'))viewer.close();mediaGeneration++;for(const resource of previewCache.values())if(resource.url)URL.revokeObjectURL(resource.url);previewCache.clear();}
 async function previewMime(blob,name=''){
  const bytes=new Uint8Array(await blob.slice(0,12).arrayBuffer());
  if(bytes.length>=8&&[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v))return 'image/png';
  if(bytes[0]===255&&bytes[1]===216&&bytes[2]===255)return 'image/jpeg';
  const head=String.fromCharCode(...bytes);
  if(head.startsWith('RIFF')&&head.slice(8,12)==='WEBP')return 'image/webp';
  if(head.startsWith('%PDF-'))return 'application/pdf';
  if(/\.(csv|txt)$/i.test(name)&&blob.size<=512*1024){const text=await blob.text();if(!text.includes('\u0000'))return 'text/plain';}
  return null;
 }
